CREATE TABLE "ai_conversations" ("id" UUID NOT NULL, "studentId" UUID NOT NULL, "feature" VARCHAR(80) NOT NULL, "title" VARCHAR(240) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ai_conversations_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ai_messages" ("id" UUID NOT NULL, "conversationId" UUID NOT NULL, "studentId" UUID NOT NULL, "role" VARCHAR(20) NOT NULL, "content" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ai_messages_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ai_conversations_studentId_updatedAt_idx" ON "ai_conversations"("studentId", "updatedAt"); CREATE INDEX "ai_messages_conversationId_createdAt_idx" ON "ai_messages"("conversationId", "createdAt"); CREATE INDEX "ai_messages_studentId_createdAt_idx" ON "ai_messages"("studentId", "createdAt");
ALTER TABLE "ai_conversations" ADD CONSTRAINT "ai_conversations_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ai_messages" ADD CONSTRAINT "ai_messages_conversationId_fkey" FOREIGN KEY ("conversationId") REFERENCES "ai_conversations"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ai_messages" ADD CONSTRAINT "ai_messages_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
INSERT INTO "permissions" ("key", "description") VALUES ('student_ai:read', 'Use private student AI'), ('student_ai:create', 'Create private student AI conversations') ON CONFLICT ("key") DO NOTHING; INSERT INTO "role_permissions" ("roleCode", "permissionKey") VALUES ('STUDENT','student_ai:read'),('STUDENT','student_ai:create') ON CONFLICT ("roleCode", "permissionKey") DO NOTHING;
